export interface PeerJsTarget {
  peerId: string
  code: string
  value: string
}

const SERVER_CODE_PATTERN = /^([A-Za-z0-9]{10})$/

/** Parses the target plugin peer from the public server-scoped code. */
export function parsePeerJsTarget(value: string): PeerJsTarget | null {
  const match = value.trim().match(SERVER_CODE_PATTERN)
  if (!match?.[1]) return null
  const peerId = match[1].toUpperCase()
  return { peerId, code: peerId, value: peerId }
}

export function normalizeVoiceCode(value: string): string {
  const cleaned = value.replace(/[^A-Za-z0-9:_-]/g, '')
  const target = parsePeerJsTarget(cleaned)
  if (target) return target.value
  return cleaned.toUpperCase()
}
